CREATE TEMP VIEW holdout_metrics AS SELECT * FROM metrics WHERE fit_scope = 'calibration_only' AND role = 'holdout' AND species IN ('ethyl_octanoate', 'isoamyl_acetate');
CREATE TEMP VIEW candidate_comparison AS SELECT * FROM comparison WHERE species IN ('ethyl_octanoate', 'isoamyl_acetate');
CREATE TEMP VIEW observed_temporal AS SELECT p.*, s.pulse_time_h, ((p.interval_start_h + p.interval_end_h) / 2.0 - s.pulse_time_h) AS h_postpulse, (p.observed_or_upper_bound / NULLIF(p.predicted_captured_ug, 0)) AS obs_pred_ratio FROM predictions p JOIN pulse_schedule s ON p.experiment_id = s.batch WHERE p.fit_scope = 'calibration_only' AND p.model_variant = 'equilibrium_morakul' AND p.status = 'observed' AND p.species IN ('ethyl_octanoate', 'isoamyl_acetate');
SELECT * FROM holdout_metrics;
SELECT * FROM candidate_comparison;
SELECT * FROM observed_temporal;

